import React, { useState, useEffect, useRef, memo } from "react";
import { MapContainer, TileLayer, GeoJSON } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import Slider from "react-slider";
import "./App.css";

const electionPrefixes = {
  "Президент": { 2012: "2012_president_", 2018: "2018_president_" },
  "Мэр": { 2013: "2013_mer_", 2018: "2018_mer_" },
  "Госдума": { 2016: "2016_duma_", 2021: "2021_duma_" },
  "Мосгордума": { 2014: "2014_mosgorduma_", 2019: "2019_mosgorduma_" },
  "Муниципальные": { 2017: "2017_mun_" }
};

const baseColors = {
  Путин: "#0072bc", Зюганов: "#d73027", Прохоров: "#00ff00",
  Жириновский: "#00bfff", Миронов: "#ffcc00", Грудинин: "#a50026",
  Собчак: "#00ff00", Сурайкин: "#d73027", Титов: "#70a9d8", Явлинский: "#8bc34a"
};

const getColorPalette = (level, year) => {
  if (level === "Президент" && year === 2018) return baseColors;
  return baseColors;
};

const loadGeoData = async (year, level) => {
  const prefix = electionPrefixes[level]?.[year] || "";
  const districtFile = `${process.env.PUBLIC_URL}/data/${prefix}districts.geojson`;
  const uikFile = `${process.env.PUBLIC_URL}/data/${prefix}uiks.geojson`;

  const [districtRes, uikRes] = await Promise.all([
    fetch(districtFile).then((res) => res.json()),
    fetch(uikFile).then((res) => res.json())
  ]);
  return { district: districtRes, uik: uikRes };
};

const MemoizedGeoJSON = memo(({ data, style, onEachFeature }) => (
  <GeoJSON data={data} style={style} onEachFeature={onEachFeature} />
));

function App() {
  const [year, setYear] = useState(2012);
  const [geoData, setGeoData] = useState({});
  const [activeElectionLevel, setActiveElectionLevel] = useState("Госдума");

  useEffect(() => {
    loadGeoData(year, activeElectionLevel).then(setGeoData);
  }, [year, activeElectionLevel]);

  return (
    <div className="App">
      <Slider value={year} min={2012} max={2022} onChange={setYear} />
      <MapContainer center={[55.7558, 37.6173]} zoom={10}>
        <TileLayer url="https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}" />
        {geoData.district && (
          <MemoizedGeoJSON data={geoData.district} />
        )}
        {geoData.uik && (
          <MemoizedGeoJSON data={geoData.uik} />
        )}
      </MapContainer>
    </div>
  );
}

export default App;
